//! Particles under mutual gravity, stepped on the GPU with wgpu.

use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 64;

const SHADER: &str = r#"
struct Params {
    count: u32,
    dt: f32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

// Part 1: every acceleration from the positions the step started with.
@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j = 0u; j < params.count; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

// Part 2: velocity grows by acceleration * dt, then position by new velocity * dt.
@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"#;

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    count: u32,
    dt: f32,
}

struct Input {
    steps: u32,
    dt: f64,
    pos: Vec<[f64; 2]>,
    vel: Vec<[f64; 2]>,
}

fn parse_count(tok: &str, what: &str, max: u64) -> Result<u64, String> {
    let n = match tok.parse::<u64>() {
        Ok(n) => n,
        Err(_) => {
            let f: f64 = tok
                .parse()
                .map_err(|_| format!("invalid {what}: {tok:?}"))?;
            if !f.is_finite() || f < 0.0 || f.fract() != 0.0 {
                return Err(format!("invalid {what}: {tok:?}"));
            }
            f as u64
        }
    };
    if n > max {
        return Err(format!("{what} out of range: {n}"));
    }
    Ok(n)
}

fn parse_input(text: &str) -> Result<Input, String> {
    let mut toks = text.split_whitespace();
    let mut next = |what: &str| toks.next().ok_or_else(|| format!("missing {what}"));
    let count = parse_count(next("count")?, "count", 2048)?;
    if count < 1 {
        return Err("count must be at least 1".into());
    }
    let steps = parse_count(next("steps")?, "steps", 200)? as u32;
    let num = |tok: &str| -> Result<f64, String> {
        tok.parse::<f64>()
            .map_err(|_| format!("invalid number: {tok:?}"))
    };
    let dt = num(next("dt")?)?;
    let mut pos = Vec::with_capacity(count as usize);
    let mut vel = Vec::with_capacity(count as usize);
    for _ in 0..count {
        let x = num(next("particle x")?)?;
        let y = num(next("particle y")?)?;
        let vx = num(next("particle vx")?)?;
        let vy = num(next("particle vy")?)?;
        pos.push([x, y]);
        vel.push([vx, vy]);
    }
    Ok(Input { steps, dt, pos, vel })
}

fn to_f32(v: &[[f64; 2]]) -> Vec<[f32; 2]> {
    v.iter().map(|p| [p[0] as f32, p[1] as f32]).collect()
}

/// Runs every step on the GPU and returns the final positions and velocities.
fn simulate(input: &Input) -> Result<(Vec<[f32; 2]>, Vec<[f32; 2]>), String> {
    let count = input.pos.len() as u32;
    let pos = to_f32(&input.pos);
    let vel = to_f32(&input.vel);

    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
        label: None,
        required_features: wgpu::Features::empty(),
        required_limits: adapter.limits(),
        memory_hints: wgpu::MemoryHints::default(),
        trace: wgpu::Trace::Off,
    }))
    .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("particles"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let params = Params {
        count,
        dt: input.dt as f32,
    };
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC;
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("pos"),
        contents: bytemuck::cast_slice(&pos),
        usage: storage,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("vel"),
        contents: bytemuck::cast_slice(&vel),
        usage: storage,
    });
    let bytes = (count as u64) * 8;
    let acc_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("acc"),
        size: bytes,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: bytes * 2,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let pipeline = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: None,
            module: &shader,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accelerate = pipeline("accelerate");
    let integrate = pipeline("integrate");

    let entries = [
        wgpu::BindGroupEntry {
            binding: 0,
            resource: params_buf.as_entire_binding(),
        },
        wgpu::BindGroupEntry {
            binding: 1,
            resource: pos_buf.as_entire_binding(),
        },
        wgpu::BindGroupEntry {
            binding: 2,
            resource: vel_buf.as_entire_binding(),
        },
        wgpu::BindGroupEntry {
            binding: 3,
            resource: acc_buf.as_entire_binding(),
        },
    ];
    let accel_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("accelerate"),
        layout: &accelerate.get_bind_group_layout(0),
        entries: &entries,
    });
    let integ_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("integrate"),
        layout: &integrate.get_bind_group_layout(0),
        entries: &entries,
    });

    let groups = count.div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&Default::default());
    for _ in 0..input.steps {
        // Separate passes so all accelerations finish before any position moves.
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&accelerate);
            pass.set_bind_group(0, &accel_group, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&integrate);
            pass.set_bind_group(0, &integ_group, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &readback, 0, bytes);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &readback, bytes, bytes);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::Wait)
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("GPU readback lost: {e}"))?
        .map_err(|e| format!("GPU readback failed: {e}"))?;
    let data: Vec<[f32; 2]> = bytemuck::cast_slice(&slice.get_mapped_range()).to_vec();
    readback.unmap();
    let n = count as usize;
    Ok((data[..n].to_vec(), data[n..].to_vec()))
}

/// Formats with six decimals, never printing a negative zero.
fn fmt(v: f64) -> String {
    let s = format!("{v:.6}");
    if s.trim_start_matches('-').bytes().all(|b| b == b'0' || b == b'.') {
        s.trim_start_matches('-').to_string()
    } else {
        s
    }
}

fn run() -> Result<(), String> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: gpu-particles <input-file>")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let input = parse_input(&text)?;

    let (pos, vel): (Vec<[f64; 2]>, Vec<[f64; 2]>) = if input.steps == 0 {
        (input.pos.clone(), input.vel.clone())
    } else {
        let (p, v) = simulate(&input)?;
        let widen = |v: Vec<[f32; 2]>| v.iter().map(|a| [a[0] as f64, a[1] as f64]).collect();
        (widen(p), widen(v))
    };

    let n = pos.len() as f64;
    let cx = pos.iter().map(|p| p[0]).sum::<f64>() / n;
    let cy = pos.iter().map(|p| p[1]).sum::<f64>() / n;
    let mx = vel.iter().map(|v| v[0]).sum::<f64>();
    let my = vel.iter().map(|v| v[1]).sum::<f64>();
    let ke = vel
        .iter()
        .map(|v| (v[0] * v[0] + v[1] * v[1]) / 2.0)
        .sum::<f64>();
    let spread = (pos
        .iter()
        .map(|p| (p[0] - cx).powi(2) + (p[1] - cy).powi(2))
        .sum::<f64>()
        / n)
        .sqrt();

    println!("CENTER {} {}", fmt(cx), fmt(cy));
    println!("MOMENTUM {} {}", fmt(mx), fmt(my));
    println!("KINETIC {}", fmt(ke));
    println!("SPREAD {}", fmt(spread));
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
